import {STORAGE_KEY,CURRENCIES,CATEGORIES,today,emptyLedger,money,validDate,toMinor,validateLedger,selectEntries,totals,escapeHTML as esc,csv,periodRange,demoLedger} from './core.mjs';
import {makePDF} from './report.mjs';
const $=s=>document.querySelector(s);
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',arrows:'<path d="M4 7h16m-5-5 5 5-5 5M20 17H4m5-5-5 5 5 5"/>',chart:'<path d="M4 3v18h17M9 17v-5m5 5V7m5 10V3"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 2v4l4 3 3-1 3 1 4-3v-4l2-2-2-4-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 3h.01"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',trend:'<path d="m3 17 6-6 4 3 8-9m-6 0h6v6"/>','arrow-up-right':'<path d="M6 18 18 6M6 6h12v12"/>','arrow-down-left':'<path d="M18 6 6 18M6 6v12h12"/>',donut:'<path d="M11 3a9 9 0 1 0 10 10H11Z"/><path d="M15 3v6h6a7 7 0 0 0-6-6Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15Z"/>',bag:'<path d="M5 7h14l2 14H3ZM8 8V6a4 4 0 0 1 8 0v2"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;}
Object.assign(icons,{moon:'<path d="M20.5 13.1A8.5 8.5 0 0 1 10.9 3.5a8.5 8.5 0 1 0 9.6 9.6Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>'});
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
function syncThemeControl(){const dark=document.documentElement.dataset.theme==='dark',button=$('#theme-toggle');const label=`Switch to ${dark?'day':'night'} mode`;button.setAttribute('aria-label',label);button.setAttribute('aria-pressed',String(dark));button.title=label;button.innerHTML=icon(dark?'sun':'moon')+`<span>${dark?'Day':'Night'}</span>`;}
document.addEventListener('biztrack-themechange',syncThemeControl);
$('#theme-toggle').addEventListener('click',()=>document.dispatchEvent(new CustomEvent('biztrack-theme-set',{detail:document.documentElement.dataset.theme==='dark'?'light':'dark'})));
syncThemeControl();
let storageBlocked=false,rawRecovery=null;
function load(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return emptyLedger();rawRecovery=raw;return validateLedger(JSON.parse(raw));}catch(e){storageBlocked=true;$('#storage-warning').hidden=false;$('#storage-warning').textContent='Your saved data could not be read. Existing browser data has been preserved. Restore a valid BizTrack backup in Settings to continue.';return emptyLedger();}}
let real=load(),ledger=real,demo=false,period='month',month=today().slice(0,7),currency=ledger.defaultCurrency,view='overview',editing=null,undoEntry=null,toastTimer,confirmCallback;
const titles={overview:['Business overview','Sales, expenses and profit at a glance.'],transactions:['Every transaction','The details behind your business.'],reports:['Business reports','Your numbers, ready to take with you.'],settings:['Your workspace','Simple preferences. Peace of mind.']};
function currencyOptions(){return Object.entries(CURRENCIES).map(([code,v])=>`<option value="${code}">${code} · ${v.name}</option>`).join('');}
for(const id of ['entry-currency','default-currency','report-currency'])$('#'+id).innerHTML=currencyOptions();
$('#currency-filter').innerHTML=Object.keys(CURRENCIES).map(code=>`<option value="${code}">${code}</option>`).join('');
$('#month-filter').value=month;$('#month-filter').min='1900-01';$('#month-filter').max='9999-12';$('#date').min='1900-01-01';$('#date').max='9999-12-31';
const initialRange=periodRange('month');$('#report-from').value=initialRange.from;$('#report-to').value=initialRange.to;$('#report-currency').value=currency;
for(const id of ['report-from','report-to']){$('#'+id).min='1900-01-01';$('#'+id).max='9999-12-31';}
function toast(message,undo=false){clearTimeout(toastTimer);$('#toast-message').textContent=message;$('#undo-delete').hidden=!undo;$('#toast').hidden=false;toastTimer=setTimeout(()=>{$('#toast').hidden=true;undoEntry=null;},undo?15000:4500);}
function save(next,{restore=false}={}){try{const valid=validateLedger(next);for(const c of Object.keys(CURRENCIES))totals(valid.entries.filter(e=>e.currency===c));if(demo){ledger=valid;return true;}if(storageBlocked&&!restore)throw Error('Storage needs attention. Restore a valid backup before saving.');localStorage.setItem(STORAGE_KEY,JSON.stringify(valid));real=ledger=valid;storageBlocked=false;$('#storage-warning').hidden=true;$('#storage-status').textContent='Saved on this device';return true;}catch(e){$('#storage-status').textContent='Could not save';toast(e.name==='QuotaExceededError'?'Browser storage is full. Download a backup to protect your records.':e.message);return false;}}
function download(data,name,type){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function filename(extension,report=false){return `biztrack-${demo?'demo-':''}${report?$('#report-currency').value:currency}-${today()}.${extension}`;}
function range(){return periodRange(period,month);}
function filtered(){return selectEntries(ledger.entries,{...range(),currency});}
function niceDate(d,full=false){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',...(full?{year:'numeric'}:{})}).format(new Date(d+'T12:00:00'));}
function refresh(){document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==`view-${view}`);document.querySelectorAll('nav a').forEach(a=>{if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#page-title').innerHTML=esc(titles[view][0])+'<span>.</span>';$('#page-subtitle').textContent=titles[view][1];$('#breadcrumb').textContent=view[0].toUpperCase()+view.slice(1);$('#business-eyebrow').textContent=ledger.businessName;$('#demo-banner').hidden=!demo;$('#global-filters').hidden=!['overview','transactions'].includes(view);$('.heading-actions').hidden=['reports','settings'].includes(view);$('#currency-filter').value=currency;$('#month-filter').hidden=period!=='month';document.querySelectorAll('[data-period]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.period===period)));if(view==='overview')renderOverview();if(view==='transactions')renderTransactions();if(view==='reports')renderReports();if(view==='settings'){$('#business-name').value=ledger.businessName;$('#default-currency').value=ledger.defaultCurrency;$('#backup-status').textContent=ledger.lastBackup?`Last backup download: ${niceDate(ledger.lastBackup,true)}`:'No backup downloaded yet';}}
function renderOverview(){const entries=filtered(),t=totals(entries);$('#profit-value').textContent=money(t.profit,currency);$('#sales-value').textContent=money(t.sales,currency);$('#expenses-value').textContent=money(t.expenses,currency);$('#sales-count').textContent=`${t.salesCount} ${t.salesCount===1?'sale':'sales'} recorded`;$('#expenses-count').textContent=`${t.expenseCount} ${t.expenseCount===1?'expense':'expenses'} recorded`;$('#margin-tag').textContent=t.margin===null?'— margin':`${Number(t.margin.toFixed(1)).toLocaleString('en-GB')}% margin`;$('#profit-description').textContent=t.profit<0?'Expenses exceed sales':'Sales minus expenses';$('#recent-count').textContent=String(entries.length);$('#recent-list').innerHTML=table(entries.slice(0,5));renderChart(entries);const categories=new Map();entries.filter(e=>e.type==='expense').forEach(e=>categories.set(e.category,(categories.get(e.category)||0)+e.amount));$('#category-breakdown').innerHTML=categories.size?'<div class="category-list">'+[...categories].sort((a,b)=>b[1]-a[1]).map(([name,amount])=>`<div class="category-item"><div class="category-top"><strong>${esc(name)}</strong><span>${money(amount,currency)} · ${Math.round(amount/t.expenses*100)}%</span></div><div class="category-track"><span style="width:${amount/t.expenses*100}%"></span></div></div>`).join('')+'</div>':`<div class="category-empty">${icon('donut')}<p>Your expense breakdown will appear here as you add entries.</p></div>`;}
function renderChart(entries){let bins=[];let caption='';if(period==='today'){bins=[{from:today(),to:today(),label:'Today'}];caption='Today’s activity';}else if(period==='month'){const end=Number(range().to.slice(-2));for(let start=1;start<=end;start+=5){const last=Math.min(start+4,end);bins.push({from:`${month}-${String(start).padStart(2,'0')}`,to:`${month}-${String(last).padStart(2,'0')}`,label:start===last?String(start):`${start}–${last}`});}caption=new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric'}).format(new Date(month+'-01T12:00:00'))+' · daily groups';}else{const months=[...new Set(entries.map(e=>e.date.slice(0,7)))].sort().slice(-6);const list=months.length?months:[today().slice(0,7)];bins=list.map(m=>({...periodRange('month',m),label:new Intl.DateTimeFormat('en-GB',{month:'short',year:'2-digit'}).format(new Date(m+'-01T12:00:00'))}));caption='Latest 6 active months';}const values=bins.map(b=>({...b,...totals(entries.filter(e=>e.date>=b.from&&e.date<=b.to))}));const max=entries.length?Math.max(1,...values.flatMap(b=>[b.sales,b.expenses])):1000*10**CURRENCIES[currency].digits;const short=n=>new Intl.NumberFormat('en-GB',{notation:'compact',maximumFractionDigits:1}).format(n/10**CURRENCIES[currency].digits);$('#activity-chart').innerHTML=`<div class="chart-grid">${[1,.75,.5,.25,0].map(f=>`<div class="grid-line"><span>${short(max*f)}</span></div>`).join('')}</div><div class="chart-bars">${values.map(b=>`<div class="bar-group" title="${esc(b.label)}: Sales ${money(b.sales,currency)}, expenses ${money(b.expenses,currency)}"><div class="bar" style="height:${b.sales/max*100}%"></div><div class="bar expense-bar" style="height:${b.expenses/max*100}%"></div><span class="bar-date">${esc(b.label)}</span></div>`).join('')}</div>${entries.length?'':'<div class="chart-empty">Your next sale starts the story.</div>'}`;$('#activity-chart').setAttribute('role','img');$('#activity-chart').setAttribute('aria-label',`${caption}. ${values.map(b=>`${b.label}: sales ${money(b.sales,currency)}, expenses ${money(b.expenses,currency)}`).join('. ')}`);$('#chart-caption').textContent=caption;$('#chart-currency').textContent=currency;}
function table(entries,report=false){if(!entries.length){const has=ledger.entries.length>0;return `<div class="empty-state"><div class="empty-mark">${icon('bag')}</div><h3>${report?'No entries in this report':has?'No transactions in this view':'A fresh start for your business.'}</h3><p>${report||has?'Try another period or currency to see your records.':'Record your first sale or expense. We’ll take care of the numbers.'}</p>${report?'':`<div class="empty-actions"><button class="button primary" data-action="add-sale">${icon('plus')}Add a sale</button>${has?'':'<button class="text-button" data-action="demo-start">Explore a demo →</button>'}</div>`}</div>`;}return `<div class="table-head"><span>Transaction</span><span>Date</span><span class="category-col">Category</span><span class="amount">Amount</span><span></span></div>`+entries.map(e=>`<${report?'div':'button type="button"'} class="entry-row${report?' report-row':''}" ${report?'':`data-edit="${esc(e.id)}" aria-label="Edit ${esc(e.description)}"`}><span class="entry-desc"><span class="entry-symbol ${e.type}">${icon(e.type==='sale'?'arrow-up-right':'arrow-down-left')}</span><span class="entry-title"><span class="entry-name">${esc(e.description)}</span><span class="entry-kind">${e.type==='sale'?'Sale':'Expense'}<span class="entry-category"> · ${esc(e.category)}</span></span></span></span><span class="entry-date">${niceDate(e.date,true)}</span><span class="category-pill">${esc(e.category)}</span><span class="entry-amount ${e.type}">${e.type==='sale'?'+':'−'}${money(e.amount,e.currency)}</span><span class="edit-symbol">${report?'':icon('edit')}</span></${report?'div':'button'}>`).join('');}
function renderTransactions(){const entries=selectEntries(ledger.entries,{...range(),currency,type:$('#type-filter').value,search:$('#search').value});$('#transaction-list').innerHTML=table(entries);}
function getReport(){const from=$('#report-from').value,to=$('#report-to').value,c=$('#report-currency').value;if(!validDate(from)||!validDate(to)||from>to)throw Error('Choose valid dates with the start on or before the end.');return {entries:selectEntries(ledger.entries,{from,to,currency:c}),options:{businessName:ledger.businessName,currency:c,from,to}};}
function renderReports(){try{const {entries,options}=getReport(),t=totals(entries);$('#report-error').textContent='';$('#report-period').textContent=`${niceDate(options.from,true)} – ${niceDate(options.to,true)}`;$('#report-count').textContent=`${entries.length} ${entries.length===1?'entry':'entries'} · ${options.currency}`;$('#report-summary').innerHTML=`<div class="report-summary-body"><div class="summary-line"><span>Total sales</span><strong>${money(t.sales,options.currency)}</strong></div><div class="summary-line"><span>Total expenses</span><strong>${money(t.expenses,options.currency)}</strong></div><div class="summary-line profit"><span>Net profit</span><strong>${money(t.profit,options.currency)}</strong></div><p class="help-text">Based on ${entries.length} recorded transactions.</p></div>`;$('#report-list').innerHTML=table(entries,true);}catch(e){$('#report-error').textContent=e.message;$('#report-summary').textContent='Choose a valid report period.';$('#report-period').textContent='';$('#report-count').textContent='';$('#report-list').innerHTML='';}}
function confirm(title,message,label,callback){$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;$('#confirm-action').textContent=label;confirmCallback=callback;$('#confirm-dialog').showModal();}
$('#confirm-action').addEventListener('click',()=>{$('#confirm-dialog').close();const fn=confirmCallback;confirmCallback=null;fn?.();});
function updateEntryType(category){const type=$('input[name=type]:checked').value;$('#category').innerHTML=CATEGORIES[type].map(c=>`<option>${esc(c)}</option>`).join('');if(category&&CATEGORIES[type].includes(category))$('#category').value=category;$('#entry-title').textContent=editing?`Edit ${type}`:`Record ${type==='sale'?'a sale':'an expense'}`;$('#save-entry').textContent=editing?'Save changes':`Save ${type}`;$('#description').placeholder=type==='sale'?'e.g. Product sale':'e.g. Stock for the shop';}
function updateAmountCurrency(){const c=$('#entry-currency').value;$('#amount-currency').textContent=c;$('#amount').step=CURRENCIES[c].digits?'0.01':'1';$('#amount').min=CURRENCIES[c].digits?'0.01':'1';}
function openEntry(type='sale',entry=null){editing=entry?.id||null;$('#entry-form').reset();$('#entry-error').textContent='';$(`input[name=type][value=${entry?.type||type}]`).checked=true;$('#entry-currency').value=entry?.currency||currency;updateAmountCurrency();$('#amount').value=entry?(entry.amount/10**CURRENCIES[entry.currency].digits).toFixed(CURRENCIES[entry.currency].digits):'';$('#description').value=entry?.description||'';$('#date').value=entry?.date||today();updateEntryType(entry?.category);$('#delete-entry').hidden=!entry;$('#entry-dialog').showModal();$('#amount').focus();}
$('#entry-form').addEventListener('submit',e=>{e.preventDefault();try{const type=$('input[name=type]:checked').value,c=$('#entry-currency').value;const entry={id:editing||crypto.randomUUID(),type,currency:c,amount:toMinor($('#amount').value,c),description:$('#description').value.trim(),date:$('#date').value,category:$('#category').value};if(!entry.description)throw Error('Add a short description.');if(!validDate(entry.date))throw Error('Choose a valid date.');const next={...ledger,entries:[...ledger.entries.filter(e=>e.id!==editing),entry]};if(!save(next)){$('#entry-error').textContent='The entry was not saved. Check the message below.';return;}$('#entry-dialog').close();refresh();toast(editing?'Transaction updated.':'Transaction saved.');}catch(error){$('#entry-error').textContent=error.message;}});
$('#delete-entry').addEventListener('click',()=>{const entry=ledger.entries.find(e=>e.id===editing);if(!entry)return;if(save({...ledger,entries:ledger.entries.filter(e=>e.id!==editing)})){undoEntry={entry,demo};$('#entry-dialog').close();refresh();toast('Transaction deleted.',true);}});
$('#undo-delete').addEventListener('click',()=>{if(undoEntry&&undoEntry.demo===demo&&!ledger.entries.some(e=>e.id===undoEntry.entry.id)){if(save({...ledger,entries:[...ledger.entries,undoEntry.entry]})){undoEntry=null;refresh();toast('Transaction restored.');}}});
document.querySelectorAll('input[name=type]').forEach(e=>e.addEventListener('change',()=>updateEntryType()));$('#entry-currency').addEventListener('change',updateAmountCurrency);
function backup(){const data={...ledger,lastBackup:today()};download(JSON.stringify(data,null,2),`biztrack-${demo?'demo-':''}backup-${today()}.json`,'application/json');save(data);if(view==='settings')refresh();toast(demo?'Demo backup downloaded.':'Backup downloaded. Keep it somewhere safe.');}
function startDemo(){if(demo){location.hash='overview';return;}$('#help-dialog').close();ledger=demoLedger();demo=true;currency='XAF';period='month';month=today().slice(0,7);$('#month-filter').value=month;$('#report-currency').value='XAF';undoEntry=null;location.hash='overview';view='overview';refresh();toast('You’re exploring sample data. Your records are safe.');}
function exitDemo(){real=load();ledger=real;demo=false;currency=real.defaultCurrency;$('#report-currency').value=currency;undoEntry=null;refresh();toast('Back to your business.');}
const actions={
 'add-sale':()=>openEntry('sale'),'add-expense':()=>openEntry('expense'),backup,
 help:()=>$('#help-dialog').showModal(),'demo-start':startDemo,'demo-exit':exitDemo,
 restore:()=>{if(demo){toast('Exit demo to restore your own backup.');return;}$('#restore-file').value='';$('#restore-file').click();},
 'csv-history':()=>{const entries=selectEntries(ledger.entries,{...range(),currency,type:$('#type-filter').value,search:$('#search').value});download(csv(entries,currency),filename('csv'),'text/csv;charset=utf-8');toast('Current view exported as CSV.');},
 'csv-report':()=>{try{const {entries,options}=getReport();download(csv(entries,options.currency),filename('csv',true),'text/csv;charset=utf-8');toast('Report exported as CSV.');}catch(e){$('#report-error').textContent=e.message;}},
 pdf:async()=>{const btn=$('[data-action=pdf]');try{const {entries,options}=getReport();if(entries.length>5000)throw Error('Choose a shorter period for PDF reports (up to 5,000 entries). CSV supports the full ledger.');btn.disabled=true;btn.textContent='Preparing PDF…';const blob=await makePDF(entries,options);download(blob,filename('pdf',true));toast('PDF report downloaded.');}catch(e){$('#report-error').textContent=e.message;}finally{btn.disabled=false;btn.innerHTML=icon('download')+'Download PDF';}}
};
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return;}const edit=e.target.closest('[data-edit]');if(edit){const entry=ledger.entries.find(x=>x.id===edit.dataset.edit);if(entry)openEntry(entry.type,entry);return;}const action=e.target.closest('[data-action]');if(action)actions[action.dataset.action]?.();const tab=e.target.closest('[data-period]');if(tab){period=tab.dataset.period;refresh();}});
$('#restore-file').addEventListener('change',async()=>{const file=$('#restore-file').files[0];if(!file)return;try{if(file.size>25*1024*1024)throw Error('Choose a backup smaller than 25 MB.');const restored=validateLedger(JSON.parse(await file.text()));for(const c of Object.keys(CURRENCIES))totals(restored.entries.filter(e=>e.currency===c));confirm('Restore this backup?',`${restored.businessName} · ${restored.entries.length} transactions · Default ${restored.defaultCurrency}\n\nThis replaces the ${real.entries.length} entries currently on this device. Download a backup first if you want to keep them.`,'Restore backup',()=>{if(rawRecovery&&storageBlocked)download(rawRecovery,`biztrack-recovery-${today()}.txt`,'text/plain');if(save(restored,{restore:true})){currency=restored.defaultCurrency;$('#report-currency').value=currency;refresh();toast('Backup restored. Your business is ready.');}});}catch(e){toast(e instanceof SyntaxError?'That file is not valid JSON. Your data was not changed.':e.message);}});
$('#settings-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#business-name').value.trim();if(!name){$('#settings-error').textContent='Enter your business name.';return;}if(save({...ledger,businessName:name,defaultCurrency:$('#default-currency').value})){currency=ledger.defaultCurrency;$('#report-currency').value=currency;$('#settings-error').textContent='';refresh();toast('Preferences saved.');}});
$('#currency-filter').addEventListener('change',()=>{currency=$('#currency-filter').value;refresh();});$('#month-filter').addEventListener('change',()=>{if(/^\d{4}-\d{2}$/.test($('#month-filter').value)){month=$('#month-filter').value;period='month';refresh();}});
$('#search').addEventListener('input',renderTransactions);$('#type-filter').addEventListener('change',renderTransactions);for(const id of ['report-from','report-to','report-currency'])$('#'+id).addEventListener('change',renderReports);
function route(){const hash=location.hash.slice(1);view=Object.hasOwn(titles,hash)?hash:'overview';refresh();}window.addEventListener('hashchange',route);
window.addEventListener('storage',e=>{if(e.key!==STORAGE_KEY||demo)return;real=ledger=load();refresh();toast('Workspace updated from another tab.');});
route();
